          "ko": "별의 수와 서열을 계산하며 자신의 위치를 확인하려는 아브라함의 모습은, SNS에서 팔로워 수와 타인의 평가에 전전긍긍하는 우리의 모습과 소름 돋게 똑같다.",
          "zho": "亚伯拉罕计算星辰和阶层的样子，简直就是我们每天盯着社交媒体关注数和点赞量焦虑的真实写照。",
