          "th": "การที่อับราฮัมพยายามนับดวงดาวและจัดลำดับชั้นนั้น เหมือนกับพวกเราที่คอยกังวลเรื่องจำนวนผู้ติดตามและยอดไลก์บนโซเชียลมีเดียไม่มีผิด",
