          "ja": "星の数ほどある宇宙の広大さと自分の小ささを突きつけられると、悩みなんてどうでもよくなる不思議な感覚。",
          "en": "Being reminded of the sheer scale of the cosmos is the ultimate reality check for how small my daily worries actually are.",
