    "2026-01-12": {
        date: "2026-01-12",
        scripture: {
          "ja": "旧約聖書",
          "en": "Old Testament",
          "ko": "Old Testament",
          "zho": "旧約聖書",
          "es": "Old Testament",
          "pt": "Old Testament",
          "vi": "Old Testament",
          "tl": "Old Testament",
          "th": "Old Testament",
          "sw": "Old Testament"
        },
        chapter: {
          "ja": "創世記 1:1-5",
          "en": "Genesis 1:1-5",
          "ko": "Genesis 1:1-5",
          "zho": "創世記 1:1-5",
          "es": "Genesis 1:1-5",
          "pt": "Genesis 1:1-5",
          "vi": "Genesis 1:1-5",
          "tl": "Genesis 1:1-5",
          "th": "Genesis 1:1-5",
          "sw": "Genesis 1:1-5"
        },
        comment: {
          "ja": "無から世界を創り出す神の壮大なプロジェクトの幕開けだけど、最初の仕事が光と闇を分けることだなんて、なんだか大掃除の第一歩を見ているようで親近感がわく。",
          "en": "God kicking off the creation of the universe by just organizing light and dark feels like the ultimate relatable first step of a massive home renovation project.",
          "ko": "세상을 창조하는 거대한 프로젝트의 시작이 고작 빛과 어둠을 나누는 일이라니, 거창한 계획을 세우고 결국은 방 정리부터 시작하는 우리들의 모습과 다를 게 없다.",
          "zho": "神創造宇宙的宏大工程，起手式居然只是把光和暗分開，這簡直就像是我們面對大掃除時那種先從分類開始的既視感。",
          "es": "Dios comenzando la creación del universo simplemente poniendo orden entre la luz y la oscuridad es el recordatorio perfecto de que hasta los grandes proyectos empiezan con una pequeña organización.",
          "pt": "Deus começando a criação do universo apenas separando a luz das trevas é como aquele primeiro passo de organização que a gente dá antes de encarar um projeto gigante.",
          "vi": "Việc Chúa bắt đầu tạo dựng vũ trụ bằng cách phân chia ánh sáng và bóng tối giống như cách chúng ta bắt đầu một dự án lớn bằng việc dọn dẹp ngăn nắp vậy.",
          "tl": "Ang paglikha ng mundo na nagsimula sa paghihiwalay ng liwanag at dilim ay parang pag-aayos ng gamit bago magsimula ng isang malaking proyekto sa bahay.",
          "th": "การที่พระผู้เป็นเจ้าทรงเริ่มสร้างจักรวาลด้วยการแยกแสงสว่างออกจากความมืดนั้น ช่างดูเหมือนการเริ่มต้นจัดบ้านก่อนจะลงมือทำโปรเจกต์ใหญ่ที่เรารู้สึกคุ้นเคยดี",
          "sw": "Mungu kuanza uumbaji kwa kutenganisha nuru na giza ni kama vile hatua ya kwanza ya kupanga vitu kabla ya kuanza mradi mkubwa wa ukarabati nyumbani."
        }
    },
