          "ja": "敵陣のど真ん中で恐れずに言葉を放つエノク、メンタルが強すぎて現代のSNS炎上案件なら即座にミュートされそうなレベル。",
          "en": "Enoch walking into the middle of hostile territory to speak his mind is a level of guts that would get him instantly cancelled on modern social media.",
          "ko": "적진 한복판에서 두려움 없이 할 말을 다 하는 에녹을 보니 현대 사회의 키보드 워리어와는 차원이 다른 강철 멘탈이 느껴진다.",
          "zho": "以諾在敵營中毫不畏懼地直言不諱，這種強大的心理素質放在現代網路世界，絕對是引發熱議的狠角色。",
          "es": "Enoch entrando en territorio enemigo sin miedo a decir la verdad tiene una valentía que haría que lo bloquearan en cualquier red social actual.",
