          "zho": "看著工匠們將會幕的細節做到精確無誤，簡直就是強迫症晚期患者在趕最後期限的真實寫照。",
          "es": "Ver a los artesanos seguir cada detalle técnico al pie de la letra me recuerda a cuando uno intenta que todo salga perfecto bajo presión.",
