        chapter: {
          "ja": "詩篇 1:1-6",
          "en": "Psalms 1:1-6",
          "ko": "Psalms 1:1-6",
          "zho": "詩篇 1:1-6",
          "es": "Psalms 1:1-6",
          "pt": "Psalms 1:1-6",
          "vi": "Psalms 1:1-6",
          "tl": "Psalms 1:1-6",
          "th": "Psalms 1:1-6",
          "sw": "Psalms 1:1-6"
        },
        comment: {
          "ja": "悪人の集まりには近づくなと釘を刺す詩篇1篇、結局のところ環境が人間を形成するという、現代のSNS断捨離と全く同じことを言っている。",
          "en": "Psalm 1 telling us to avoid the company of scoffers is basically just an ancient, divine version of curating your social media feed for better mental health.",
          "ko": "악인의 꾀를 좇지 말라는 시편 1편의 조언은 결국 주변 환경이 내 멘탈을 만든다는 현대의 SNS 다이어트와 일맥상통한다.",
          "zho": "诗篇第1篇告诫不要与恶人同坐，这简直就是古老的断舍离指南，告诉我们环境对心态的影响有多大。",
          "es": "El Salmo 1 nos advierte sobre no juntarnos con gente tóxica, lo cual es básicamente un consejo milenario para cuidar nuestra salud mental en la era digital.",
          "pt": "O Salmo 1 avisando para não andar com escarnecedores é basicamente um conselho milenar sobre como filtrar o seu feed de redes sociais para manter a paz mental.",
          "vi": "Thi thiên 1 khuyên chúng ta nên tránh xa những kẻ nhạo báng, nghe chẳng khác nào lời khuyên hiện đại về việc thanh lọc mạng xã hội để giữ tinh thần lạc quan.",
          "tl": "Ang payo ng Awit 1 na huwag sumama sa mga mapanlait ay parang sinaunang bersyon ng pag-unfollow sa mga toxic na tao sa social media para sa iyong peace of mind.",
          "th": "สดุดีบทที่ 1 ที่สอนไม่ให้คบคนพาล ก็คือคำแนะนำเรื่องการคัดกรองเพื่อนในโซเชียลมีเดียเพื่อสุขภาพจิตที่ดีในยุคปัจจุบันนั่นเอง",
          "sw": "Zaburi 1 inayotushauri kuepuka watu wabaya ni kama ushauri wa kisasa wa kuchuja watu unaowafuatilia kwenye mitandao ya kijamii ili kulinda amani yako ya akili."
        }
