        chapter: {
          "ja": "エレミヤ書 17:1-27",
          "en": "Jeremiah 17:1-27",
          "ko": "Jeremiah 17:1-27",
          "zho": "エレミヤ書 17:1-27",
          "es": "Jeremiah 17:1-27",
          "pt": "Jeremiah 17:1-27",
          "vi": "Jeremiah 17:1-27",
          "tl": "Jeremiah 17:1-27",
          "th": "Jeremiah 17:1-27",
          "sw": "Jeremiah 17:1-27"
        },
        comment: {
          "ja": "心に罪を刻み込むなんて物騒なことを言われているけれど、結局のところ人は誰しも自分の都合の良いことしか覚えていないのがリアルなところだ。",
          "en": "They talk about sins being engraved on the heart, but let’s be honest, we all have a selective memory when it comes to our own mistakes.",
          "ko": "죄가 마음에 새겨진다는 무시무시한 경고를 듣지만, 사실 우리 모두는 자기 잘못은 금방 잊어버리는 선택적 기억력을 가지고 있잖아요.",
          "zho": "虽然说罪孽被刻在心版上听起来很可怕，但说实话，谁还没个选择性记忆，专门记别人的错而忽略自己的呢。",
          "es": "Dicen que el pecado queda grabado en el corazón, pero siendo sinceros, todos tenemos una memoria muy selectiva cuando se trata de reconocer nuestros propios errores.",
          "pt": "Dizem que o pecado fica gravado no coração, mas sejamos honestos, todos nós temos uma memória muito seletiva quando o assunto é reconhecer os próprios erros.",
          "vi": "Dù lời cảnh báo về việc tội lỗi khắc sâu trong lòng nghe thật đáng sợ, nhưng thực tế là ai trong chúng ta cũng có trí nhớ chọn lọc khi nghĩ về lỗi lầm của chính mình.",
          "tl": "Sinasabing ang kasalanan ay nakaukit sa puso, pero sa totoo lang, lahat tayo ay may selective memory pagdating sa sarili nating mga pagkakamali.",
          "th": "คำเตือนเรื่องบาปที่ถูกสลักไว้ในใจฟังดูน่ากลัว แต่เอาเข้าจริงเราทุกคนต่างก็มีความจำแบบเลือกจำเวลาที่ต้องยอมรับความผิดของตัวเอง",
          "sw": "Wanasema dhambi huchorwa moyoni, lakini ukweli ni kwamba sote tuna kumbukumbu za kuchagua pale tunapokosea wenyewe."
        }
