        comment: {
          "ja": "都合の悪い報告書をナイフで切り刻んで暖炉に放り込む王様の姿は、現代の不都合なメールを未読のままゴミ箱に入れる私たちの姿と重なって笑えない。",
          "en": "The king cutting up the scroll and tossing it into the fire is basically the ancient version of deleting an email you really do not want to deal with.",
          "ko": "불편한 진실이 담긴 편지를 읽기도 전에 불태워버리는 왕의 모습에서, 읽기 싫은 메시지를 무시하고 삭제하는 우리의 일상을 본다.",
          "zho": "國王把令人不悅的報告切碎扔進火爐，這簡直就是現代人把討厭的郵件直接丟進垃圾桶的翻版。",
          "es": "El rey cortando el pergamino y echándolo al fuego es básicamente la versión antigua de ignorar ese correo electrónico que no quieres responder.",
          "pt": "O rei cortando o pergaminho e jogando no fogo é basicamente a versão antiga de deletar aquele e-mail que você não quer responder.",
          "vi": "Vị vua cắt nát cuộn giấy rồi ném vào lửa chẳng khác nào cách chúng ta xóa đi những email khó chịu mà mình không muốn đối mặt.",
          "tl": "Ang hari na pinagpipira-piraso ang sulat at itinapon sa apoy ay parang tayo lang na dinedelete ang email na ayaw nating basahin.",
          "th": "กษัตริย์ที่หั่นม้วนหนังสือแล้วโยนเข้ากองไฟนั้น ไม่ต่างอะไรกับเราที่กดลบอีเมลที่ไม่อยากอ่านทิ้งไปในทันที",
          "sw": "Mfalme kukata hati na kuichoma moto ni kama tu sisi tunavyofuta barua pepe ambazo hatutaki kuzishughulikia."
        }
